type ClaimFinding = unverifiedClaimFinding

type ClaimsPageScan struct {
	PageID   string
	PageName string
	Findings []unverifiedClaimFinding
	ComponentsExamined int
	ComponentsSkippedLocked int
}

func ScanDeployedClaims(ctx context.Context, db *sql.DB, siteID uuid.UUID, pageIDFilter string, eb *datahelpers.EvidenceBase, rowExists bool, logger *zap.Logger) ([]*ClaimsPageScan, []unverifiedClaimFinding, error) {
	pageQuery := `
		SELECT pc.page_id::text, p.name, COALESCE(pc.slot_name, ''),
		       COALESCE(pc.rendered_html, ''), COALESCE(cc.name, ''),
		       COALESCE(pc.content_data::text, ''), COALESCE(p.page_type, ''),
		       pc.locked_at
		FROM page_components pc
		JOIN pages p ON p.id = pc.page_id
		LEFT JOIN content_components cc ON cc.id = pc.component_id
		WHERE p.site_id = $1
		  AND ( (pc.rendered_html IS NOT NULL AND pc.rendered_html <> '')
		     OR (pc.content_data IS NOT NULL AND pc.content_data::text <> '{}') )`
	if strings.TrimSpace(pageIDFilter) != "" {
		pageQuery += ` AND pc.page_id = $2::uuid`
		pageArgs = append(pageArgs, strings.TrimSpace(pageIDFilter))
	}
	...
	if lockedAt.Valid {
		pf.ComponentsSkippedLocked++
		continue
	}
	pf.ComponentsExamined++
	// scans unchanged, appended to pf.Findings
	return pageOrder, siteFindings, nil
}

// NOTE: no p.status filter — this check has never had one, and the
// revalidator must judge by the emit side's exact predicate.

eb, rowExists, err := LoadEvidenceBase(dctx.Ctx, dctx.DB, dctx.SiteID)
scans, siteFindings, err := ScanDeployedClaims(dctx.Ctx, dctx.DB, dctx.SiteID, "", eb, rowExists, dctx.Logger)

pageFindings := make([]*ClaimsPageScan, 0, len(scans))
total := 0
for _, pf := range scans {
	if len(pf.Findings) == 0 { continue }
	pageFindings = append(pageFindings, pf)
	total += len(pf.Findings)
}
if len(pageFindings) == 0 && len(siteFindings) == 0 { return &CheckResult{}, nil }
total += len(siteFindings)

func unverifiedClaimsVerdict(pageID string, scan *checks.ClaimsPageScan) revalidationVerdict {
	if scan == nil { return unknown("an unbuilt page is not evidence the claims were removed") }
	if scan.ComponentsExamined == 0 { return unknown("every rendered component on this page is human-locked ... the audit examined nothing") }
	if len(scan.Findings) > 0 { return stillHolds("page %s still carries %d claim(s) the register does not support") }
	if scan.ComponentsSkippedLocked > 0 { return unknown("... human-locked component(s) were not read, and the reported claims may sit in those") }
	return resolved("re-scanned all %d component(s) ... found no unsupported claim")
}

// and, before the scan:
if !rowExists {
	return unknown("site has no current evidence_base spec ... withdrawing the register is not evidence the claims were substantiated")
}

unreadable := []*checks.ClaimsPageScan{nil, {PageID: "p1"}, {PageID: "p1", ComponentsSkippedLocked: 1}, {PageID: "p1", ComponentsSkippedLocked: 9}}
for _, scan := range unreadable {
	if unverifiedClaimsVerdict("p1", scan).Verdict == revalidationResolved {
		t.Errorf("produced `resolved` without examining a component")
	}
}

if filedAt.IsZero() {
	return unknown("this finding carries no filing date, so there is nothing to compare the page's last edit against")
}
if !scan.NewestComponentUpdate.After(filedAt) {
	return unknown("page %s no longer trips the check, but no component on it has changed since this finding was filed — so the site's evidence register moved, not the page; a register entry proves a claim was registered, never that it is true")
}
return resolved(...)  // evidence carries BOTH item_filed_at and newest_component_update
